/**
 * Buying Pro, the same way from every screen that sells it: the paywall
 * (`Upgrade`) and the Plan page. The purchase happens in the seller's own
 * sheet — Paddle's overlay on the web, Google Play's in the Android app,
 * Apple's in the iPhone app — and nothing here decides that anyone has
 * paid: the server's answer is the plan.
 *
 * With an offer (`/billing/state` `offer`), the server is asked first, every
 * time: it checks the offer is still open for this account and answers what
 * the seller needs (a Paddle transaction carrying the discount, the Play
 * offer to pick, Apple's eligibility JWS). An offer that closed in the
 * meantime (409 `offer_closed`) is not an error wall: the plan is read again
 * and the page shows the price of today.
 */
import { useRef, useState } from 'react';
import { billing as billingApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { useAuth } from '@/features/auth/session.js';
import { t } from '@/i18n/index.js';
import { useTheme } from '@/lib/theme.js';
import { openCheckout } from './paddle.js';
import { buyOnPlay, onAndroid, onIOS, type PlayOfferRefs } from './play.js';
import {
  appAccountToken,
  appStoreEligibility,
  buyOnAppStore,
  finishTransaction,
  notYours,
  PurchaseClosed,
} from './appstore.js';
import {
  PurchaseProblem,
  reportPurchaseProblem,
  type PurchaseStage as ProblemStage,
} from './purchaseProblem.js';
import type { Offer } from './offer.js';
import { useBilling } from './state.js';

export type PaidPlan = 'pro_monthly' | 'pro_yearly';

/** The plan a purchase was for, in the words the screen showed it in. */
export interface BoughtPlan {
  plan: PaidPlan;
  /** What was billed today ("$20.99"). */
  billed: string;
  /** What it renews at ("$29.99"). */
  renewal: string;
}

/** Where a purchase has got to. */
export type PurchaseStage = 'choosing' | 'waiting' | 'done';

export interface Purchase {
  /** The plan whose sheet is opening, or null. */
  busy: PaidPlan | null;
  /** What went wrong, in words, or null. */
  error: string | null;
  /** A calm line that is not a failure (an offer that closed), or null. */
  notice: string | null;
  /**
   * 'waiting' is after the seller said it charged but before the server has
   * heard; 'done' only once the server agrees, so a celebration is never a
   * promise the next screen has to take back.
   */
  stage: PurchaseStage;
  /** An App Store purchase waiting for somebody else (Ask to Buy, a bank). */
  approval: boolean;
  /** The pending approval arrived as Pro while this was open. */
  approved: boolean;
  /** Whether the purchase that finished was made at an offer's price. */
  fromOffer: boolean;
  /** What was bought, as the picker said it, for the receipt after. */
  bought: BoughtPlan | undefined;
  buy: (plan: PaidPlan, offer?: Offer, words?: Omit<BoughtPlan, 'plan'>) => void;
  /** Moves straight to the celebration (a restore that found Pro). */
  finish: () => void;
  /** Back to choosing, once the celebration has been seen. */
  reset: () => void;
}

/** Whether a failure is the server saying the offer is not open any more. */
export function offerClosed(cause: unknown): boolean {
  return isApiError(cause, 'conflict') && cause.code === 'offer_closed';
}

/** Pro arriving is the day's one big moment (features/celebrate). */
function celebrate(): void {
  void import('@/features/celebrate/state.js')
    .then((moment) => moment.noteBigMoment())
    .catch(() => undefined);
}

export function usePurchase(): Purchase {
  const state = useBilling((s) => s.state);
  const apply = useBilling((s) => s.apply);
  const refresh = useBilling((s) => s.refresh);
  const waitForPro = useBilling((s) => s.waitForPro);
  // The account the purchase is attached to. The stores carry it through,
  // and the server refuses a purchase that names anybody else.
  const accountId = useAuth((s) => s.user?.id);
  // The overlay follows the app's ground. 'system' resolves to whatever the
  // document is actually showing, which is what the theme script decided.
  const theme = useTheme((s) => s.theme);
  const dark = theme === 'system' ? document.documentElement.dataset.theme !== 'light' : theme === 'dark';
  const [busy, setBusy] = useState<PaidPlan | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [stage, setStage] = useState<PurchaseStage>('choosing');
  const [approval, setApproval] = useState(false);
  const [fromOffer, setFromOffer] = useState(false);
  const [bought, setBought] = useState<BoughtPlan | undefined>(undefined);
  // A second tap before the first has re-rendered the buttons disabled
  // would open a second store sheet.
  const buying = useRef(false);
  const approved = approval && state?.plan === 'pro';

  const done = (offered: boolean): void => {
    setFromOffer(offered);
    setStage('done');
    celebrate();
  };

  /**
   * Google Play's way: its own sheet, then the token to the server. Once
   * Play says the purchase happened, nothing that goes wrong afterwards is
   * this person's problem: Play holds it, the app still holds the token,
   * and the plan sends every token it finds each time it opens.
   */
  const buyOnAndroid = async (plan: PaidPlan, offer: Offer | undefined): Promise<void> => {
    if (accountId === undefined || accountId === '') {
      // Without the account the purchase could not be attributed to anyone.
      throw new PurchaseProblem('account', 'no_account');
    }
    let refs: PlayOfferRefs | undefined;
    if (offer?.play !== undefined) {
      // The server checks once more that the offer is open, and names the
      // Play offer to pick; a closed one is a 409 handled by the caller.
      const checkout = await billingApi.checkout(plan, { offerId: offer.id });
      const named = checkout.play ?? offer.play;
      refs = {
        productId: named.productId,
        basePlanId: named.basePlanId,
        offerId: named.offerId,
        offerTag: named.offerTag,
      };
    }
    const outcome =
      refs === undefined ? await buyOnPlay(plan, accountId) : await buyOnPlay(plan, accountId, refs);
    if (outcome.kind === 'closed') return;
    setStage('waiting');
    try {
      apply(await billingApi.verifyGooglePurchase(outcome.purchaseToken));
      done(refs !== undefined);
    } catch {
      // Stay on "payment received". Play has it; we will ask again.
    }
  };

  /**
   * Apple's way. Every purchase first gets the server's eligibility JWS
   * (fail closed: no JWS, no sheet), then Apple's sheet, the transaction to
   * the server, and only once the server agrees, the transaction finished.
   */
  const buyOnIPhone = async (plan: PaidPlan, offer: Offer | undefined): Promise<void> => {
    if (appAccountToken(accountId) === undefined) {
      // Without the account the server could not tell whose purchase it
      // is, after Apple had taken the money. Better not to open the sheet.
      throw new PurchaseProblem('account', 'bad_account');
    }
    const offerId = offer?.apple === undefined ? undefined : offer.id;
    // Fail closed: no answer from the server, no sheet.
    let terms;
    try {
      terms = await appStoreEligibility(plan, offerId);
    } catch (cause) {
      // Somebody closed the Apple Account sheet StoreKit showed on the way.
      if (cause instanceof PurchaseClosed) return;
      throw cause;
    }
    const outcome = await buyOnAppStore(plan, accountId, terms);
    if (outcome.kind === 'closed') return;
    if (outcome.kind === 'pending') {
      setApproval(true);
      return;
    }
    setStage('waiting');
    try {
      apply(
        await billingApi.verifyApplePurchase({
          transactionId: outcome.transactionId,
          ...(outcome.signedTransaction === undefined
            ? {}
            : { signedTransaction: outcome.signedTransaction }),
        }),
      );
    } catch (cause) {
      if (notYours(cause)) {
        setStage('choosing');
        setError(t('upgrade.appleNotYours'));
      }
      // Anything else: stay on "payment received". Apple has it, the
      // transaction is unfinished, and it is sent again. Still told, so a
      // server that keeps refusing a real purchase is seen.
      reportPurchaseProblem(cause, { stage: 'verify', plan, offerId });
      return;
    }
    // Finished only now, after the server has agreed.
    await finishTransaction(outcome.transactionId);
    done(offerId !== undefined);
  };

  /** Paddle's way: its overlay (on the server's transaction for an offer), then ask the server again. */
  const buyOnWeb = async (plan: PaidPlan, offer: Offer | undefined): Promise<void> => {
    const offerId = offer?.provider === 'paddle' ? offer.id : undefined;
    const checkout =
      offerId === undefined ? await billingApi.checkout(plan) : await billingApi.checkout(plan, { offerId });
    const outcome = await openCheckout(checkout, dark ? 'dark' : 'light');
    // Closed without paying: nothing happened, and saying so would be
    // telling someone off for changing their mind.
    if (outcome !== 'completed') return;
    // Paddle says it charged the card; the plan only changes once the
    // server hears that from Paddle itself.
    setStage('waiting');
    if (await waitForPro()) done(offerId !== undefined && checkout.transactionId !== undefined);
  };

  const buy = (plan: PaidPlan, offer?: Offer, words?: Omit<BoughtPlan, 'plan'>): void => {
    if (buying.current) return;
    buying.current = true;
    setBought(words === undefined ? undefined : { plan, ...words });
    setBusy(plan);
    setError(null);
    setNotice(null);
    setApproval(false);
    // An offer is only ever for its own plan.
    const deal = offer?.planId === plan ? offer : undefined;
    const bought = onIOS()
      ? buyOnIPhone(plan, deal)
      : onAndroid()
        ? buyOnAndroid(plan, deal)
        : buyOnWeb(plan, deal);
    bought
      .catch((cause: unknown) => {
        setStage('choosing');
        if (!offerClosed(cause)) {
          // The real reason, to the console and the server's log; the
          // screen says only what the learner can act on.
          const stage: ProblemStage = onIOS() || onAndroid() ? 'purchase' : 'checkout';
          reportPurchaseProblem(cause, { stage, plan, offerId: deal?.id });
        }
        if (offerClosed(cause)) {
          // Not an error: the price of today is shown once the plan is read again.
          setNotice(t('offer.closed'));
          void refresh();
        } else if (isApiError(cause, 'offline')) setError(t('error.offline'));
        else if (isApiError(cause, 'notFound')) setError(t('upgrade.closed'));
        else if (cause instanceof Error && cause.message === 'ios_too_old') setError(t('upgrade.needsIOS16'));
        else setError(t('error.generic'));
      })
      .finally(() => {
        buying.current = false;
        setBusy(null);
      });
  };

  return {
    busy,
    error,
    notice,
    stage,
    approval,
    approved,
    fromOffer,
    bought,
    buy,
    finish: () => {
      done(false);
    },
    reset: () => {
      setStage('choosing');
      setApproval(false);
    },
  };
}
