/**
 * Opening Paddle's checkout.
 *
 * Paddle's script is loaded the first time someone actually wants to buy,
 * not on every page load: most people never open it, and it is a third-party
 * script on the critical path otherwise.
 *
 * Nothing here decides that anyone has paid. The overlay closing means the
 * overlay closed; the plan changes when the server hears from Paddle, which
 * is why the caller refetches rather than assuming.
 */
import type { ApiCheckout } from '@/api/types.js';

const SCRIPT_URL = 'https://cdn.paddle.com/paddle/v2/paddle.js';

interface PaddleCheckoutOptions {
  /** A price to open, when the server did not create the transaction itself. */
  items?: { priceId: string; quantity: number }[];
  /**
   * A transaction the server already created (an offer: its discount is on
   * the transaction, and its id never reaches this page).
   */
  transactionId?: string;
  customData?: Record<string, string>;
  customer?: { email: string };
  settings?: { displayMode: string; theme: string; successUrl?: string };
}

interface PaddleGlobal {
  Initialize: (options: { token: string; eventCallback?: (event: { name: string }) => void }) => void;
  Checkout: { open: (options: PaddleCheckoutOptions) => void };
}

declare global {
  interface Window {
    Paddle?: PaddleGlobal;
  }
}

let loading: Promise<PaddleGlobal> | null = null;
/** The token Paddle was initialised with, so a second open does not redo it. */
let initialisedWith: string | null = null;
/** The caller waiting for the overlay to close, if any. */
let pending: ((outcome: CheckoutOutcome) => void) | null = null;
/** What the overlay reported before it closed. */
let outcome: CheckoutOutcome = 'closed';

/** Loads Paddle's script once, and hands back the global it defines. */
async function load(): Promise<PaddleGlobal> {
  if (window.Paddle) return window.Paddle;
  loading ??= new Promise<PaddleGlobal>((resolve, reject) => {
    const script = document.createElement('script');
    script.src = SCRIPT_URL;
    script.async = true;
    script.onload = () => {
      if (window.Paddle) resolve(window.Paddle);
      else reject(new Error('Paddle loaded but defined nothing'));
    };
    script.onerror = () => {
      // A failed load must not be remembered as a failure for ever: the next
      // attempt should be allowed to try again.
      loading = null;
      reject(new Error('Paddle could not be loaded'));
    };
    document.head.appendChild(script);
  });
  return loading;
}

/** What the caller learns when the overlay closes. */
export type CheckoutOutcome =
  /** Paddle said the payment completed. The plan follows once the server hears. */
  | 'completed'
  /** The overlay was closed without paying. */
  | 'closed';

/**
 * Opens the checkout the server described and resolves when the overlay is
 * gone. A 'completed' outcome is Paddle's word, not proof: the caller asks
 * the server what the plan is rather than believing the browser.
 */
export async function openCheckout(checkout: ApiCheckout, theme: 'dark' | 'light'): Promise<CheckoutOutcome> {
  const options = paddleOpenOptions(checkout, theme);
  const token = checkout.token;
  // A checkout Paddle cannot open (no token, or neither a transaction nor a
  // price) is a failure the caller reports, never an overlay opened blind.
  if (options === undefined || token === undefined || token === '')
    throw new Error('paddle_checkout_incomplete');
  const paddle = await load();

  // Paddle is initialised once per token and its callback lives for the life
  // of the page, so the waiting caller is kept in a module variable rather
  // than captured in a callback that is only registered the first time.
  if (initialisedWith !== token) {
    paddle.Initialize({
      token,
      eventCallback: (event) => {
        if (event.name === 'checkout.completed') outcome = 'completed';
        if (event.name === 'checkout.closed') {
          const waiting = pending;
          pending = null;
          waiting?.(outcome);
        }
      },
    });
    initialisedWith = token;
  }

  return new Promise<CheckoutOutcome>((resolve) => {
    // A checkout left open when another is started resolves as closed, so
    // nothing is left waiting for ever.
    pending?.('closed');
    outcome = 'closed';
    pending = resolve;

    paddle.Checkout.open(options);
  });
}

/**
 * What Paddle's overlay is opened with. With an offer the server has
 * created the transaction itself, carrying the offer's discount, and the
 * overlay opens on that transaction; otherwise on the plan's price. Either
 * way the account travels with the payment and comes back on Paddle's
 * notification: without it the server has nobody to give the plan to.
 * Undefined when the answer names neither.
 */
export function paddleOpenOptions(
  checkout: ApiCheckout,
  theme: 'dark' | 'light',
): PaddleCheckoutOptions | undefined {
  const common = {
    customData: { userId: checkout.customData.userId },
    ...(checkout.email === undefined ? {} : { customer: { email: checkout.email } }),
    settings: { displayMode: 'overlay', theme },
  };
  if (checkout.transactionId !== undefined && checkout.transactionId !== '') {
    return { transactionId: checkout.transactionId, ...common };
  }
  if (checkout.priceId !== undefined && checkout.priceId !== '') {
    return { items: [{ priceId: checkout.priceId, quantity: 1 }], ...common };
  }
  return undefined;
}
